const config = {
  "previewFeatures": [],
  "clientVersion": "7.7.0",
  "engineVersion": "75cbdc1eb7150937890ad5465d861175c6624711",
  "activeProvider": "postgresql",
  "inlineSchema": "// ═══════════════════════════════════════════════════════════════\n// Certa Seguros — Prisma Schema\n// CRM para corredores de seguros (Insurance Brokerage CRM)\n// ═══════════════════════════════════════════════════════════════\n\ngenerator client {\n  provider   = \"prisma-client-js\"\n  output     = \"../src/generated/prisma\"\n  engineType = \"library\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ═══════════════════════════════════════════════════════════════\n// ENUMS\n// ═══════════════════════════════════════════════════════════════\n\nenum UserRole {\n  ADMIN\n  ASESOR\n  VIEWER\n}\n\nenum ClientType {\n  INDIVIDUAL // Persona natural\n  BUSINESS // Empresa / Persona jurídica\n}\n\nenum ClientStatus {\n  ACTIVO // Cliente con póliza vigente\n  INACTIVO // Cliente inactivo\n  MOROSO // Cliente con facturas vencidas\n}\n\nenum ProspectStatus {\n  NUEVO // Recién capturado\n  CONTACTADO // Ya se hizo contacto inicial\n  EN_PROCESO // En negociación / cotización\n  DESCARTADO // No interesado / inválido\n  CONVERTIDO // Se convirtió en cliente\n}\n\nenum LeadSource {\n  WEB_PUBLICA\n  REFERIDOS\n  REDES_SOCIALES\n  DIRECTOS\n}\n\nenum InvoiceStatus {\n  DRAFT // Borrador\n  PENDING // Pendiente de pago\n  PAID // Pagada\n  OVERDUE // Vencida\n}\n\nenum PolicyStatus {\n  ACTIVE // Vigente\n  EXPIRED // Vencida\n  CANCELLED // Cancelada\n  PENDING_RENEWAL // Pendiente de renovación\n}\n\nenum PolicyType {\n  SOAT\n  VEHICULAR\n  VIDA\n  ARL\n  TODO_RIESGO\n  SALUD\n  OTRO\n}\n\nenum ReminderType {\n  RENOVACION_SOAT\n  RENOVACION_POLIZA\n  SEGUIMIENTO_ARL\n  LLAMADA\n  VISITA\n  OTRO\n}\n\nenum ReminderPriority {\n  INMEDIATA\n  CRITICA\n  ALTA\n  MEDIA\n  BAJA\n}\n\nenum ReminderStatus {\n  PENDIENTE\n  EN_PROCESO\n  COMPLETADO\n  VENCIDO\n}\n\nenum GoalCategory {\n  VENTAS\n  CLIENTES\n  RENOVACIONES\n  INGRESOS\n}\n\nenum GoalPeriod {\n  MENSUAL\n  TRIMESTRAL\n  ANUAL\n}\n\nenum GoalStatus {\n  ON_TRACK\n  AT_RISK\n  BEHIND\n  COMPLETED\n  EXCEEDED\n}\n\nenum ActivityType {\n  SUCCESS // Póliza emitida, pago recibido\n  INFO // Cotización enviada, prospecto contactado\n  WARNING // Renovación pendiente\n  DANGER // Siniestro reportado, factura vencida\n}\n\nenum DocumentType {\n  CC // Cédula de Ciudadanía\n  NIT // Número de Identificación Tributaria\n  CE // Cédula de Extranjería\n  PASAPORTE\n  TI // Tarjeta de Identidad\n  RUT // Registro Único Tributario\n}\n\nenum ServiceValidityType {\n  UNICA_VEZ\n  ANUAL\n  MENSUAL\n  TRIMESTRAL\n  SEMESTRAL\n}\n\n// ═══════════════════════════════════════════════════════════════\n// MODELOS\n// ═══════════════════════════════════════════════════════════════\n\n/// Usuarios del sistema (administradores, asesores)\n/// Autenticación delegada a Firebase Auth\nmodel User {\n  id          String   @id @default(cuid())\n  firebaseUid String   @unique // UID de Firebase Auth\n  email       String   @unique\n  name        String\n  role        UserRole @default(VIEWER)\n  avatarUrl   String?\n  isActive    Boolean  @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relaciones\n  reminders    Reminder[]\n  activityLogs ActivityLog[]\n\n  @@index([firebaseUid])\n  @@index([email])\n  @@index([role])\n  @@map(\"users\")\n}\n\n/// Clientes activos del sistema.\n/// Solo clientes que han sido convertidos de prospectos y tienen pólizas o potencial de negocio.\nmodel Client {\n  id             String        @id @default(cuid())\n  name           String\n  type           ClientType    @default(INDIVIDUAL)\n  documentType   DocumentType?\n  documentNumber String?\n  email          String?\n  phone          String?\n  address        String?\n  birthDate      DateTime? // Fecha de nacimiento (para personas naturales)\n  city           String? // Ciudad de residencia\n  notes          String? // Notas libres sobre el cliente\n  status         ClientStatus  @default(ACTIVO)\n  source         LeadSource?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relaciones\n  policies     Policy[]\n  invoices     Invoice[]\n  reminders    Reminder[]\n  activityLogs ActivityLog[]\n  services     ClientService[]\n  tags         ClientTag[]\n\n  @@index([email])\n  @@index([status])\n  @@index([type])\n  @@index([source])\n  @@index([documentNumber])\n  @@index([city])\n  @@index([birthDate])\n  @@map(\"clients\")\n}\n\n/// Prospectos (leads) que aún no se han convertido en clientes.\n/// Se gestionan en el pipeline de ventas hasta su conversión o descarte.\nmodel Prospect {\n  id             String         @id @default(cuid())\n  name           String\n  type           ClientType     @default(INDIVIDUAL)\n  documentType   DocumentType?\n  documentNumber String?\n  email          String?\n  phone          String?\n  address        String?\n  status         ProspectStatus @default(NUEVO)\n  source         LeadSource?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relaciones\n  reminders    Reminder[]\n  activityLogs ActivityLog[]\n  services     ProspectService[]\n\n  @@index([email])\n  @@index([status])\n  @@index([type])\n  @@index([source])\n  @@index([documentNumber])\n  @@map(\"prospects\")\n}\n\n/// Tags normalizados para clientes (etiquetas personalizables)\nmodel ClientTag {\n  id    String  @id @default(cuid())\n  name  String  @unique // \"VIP\", \"Frecuente\", \"Riesgo Alto\", etc.\n  color String? // Color hex para UI (#FF5733, etc.)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relación\n  clients Client[]\n\n  @@map(\"client_tags\")\n}\n\n/// Tabla pivote: servicios de interés de cada prospecto\nmodel ProspectService {\n  id         String @id @default(cuid())\n  prospectId String\n  serviceId  String\n\n  prospect Prospect @relation(fields: [prospectId], references: [id], onDelete: Cascade)\n  service  Service  @relation(fields: [serviceId], references: [id], onDelete: Cascade)\n\n  assignedAt DateTime @default(now())\n\n  @@unique([prospectId, serviceId])\n  @@map(\"prospect_services\")\n}\n\n/// Categorías principales de servicios (Seguros, Asesorías, Servicios Adicionales)\nmodel ServiceCategory {\n  id          String  @id @default(cuid())\n  name        String  @unique\n  description String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relaciones\n  subcategories ServiceSubcategory[]\n\n  @@map(\"service_categories\")\n}\n\n/// Subcategorías de servicios (Movilidad, Salud, Vida, Legal, SST)\nmodel ServiceSubcategory {\n  id          String  @id @default(cuid())\n  name        String\n  description String?\n\n  categoryId String\n  category   ServiceCategory @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relaciones\n  services Service[]\n\n  @@unique([categoryId, name])\n  @@map(\"service_subcategories\")\n}\n\n/// Catálogo de servicios ofrecidos (Seguro Todo Riesgo, Asesoría Legal, etc.)\nmodel Service {\n  id               String              @id @default(cuid())\n  name             String\n  description      String?\n  validityType     ServiceValidityType @default(ANUAL)\n  price            Decimal?            @db.Decimal(15, 2)\n  priceDescription String? // Para precios variables como \"Depende del perfil\"\n  isActive         Boolean             @default(true)\n\n  subcategoryId String?\n  subcategory   ServiceSubcategory? @relation(fields: [subcategoryId], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relaciones\n  policies  Policy[]\n  clients   ClientService[]\n  prospects ProspectService[]\n\n  @@index([isActive])\n  @@index([subcategoryId])\n  @@map(\"services\")\n}\n\n/// Tabla pivote: servicios de interés de cada prospecto/cliente\nmodel ClientService {\n  id        String @id @default(cuid())\n  clientId  String\n  serviceId String\n\n  client  Client  @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  service Service @relation(fields: [serviceId], references: [id], onDelete: Cascade)\n\n  assignedAt DateTime @default(now())\n\n  @@unique([clientId, serviceId])\n  @@map(\"client_services\")\n}\n\n/// Pólizas emitidas a clientes\nmodel Policy {\n  id               String       @id @default(cuid())\n  policyNumber     String       @unique\n  type             PolicyType\n  premiumAmount    Decimal      @db.Decimal(15, 2)\n  commissionAmount Decimal      @default(0) @db.Decimal(15, 2)\n  startDate        DateTime\n  endDate          DateTime\n  status           PolicyStatus @default(ACTIVE)\n\n  clientId  String\n  client    Client   @relation(fields: [clientId], references: [id], onDelete: Restrict)\n  serviceId String?\n  service   Service? @relation(fields: [serviceId], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([clientId])\n  @@index([status])\n  @@index([type])\n  @@index([endDate])\n  @@index([policyNumber])\n  @@map(\"policies\")\n}\n\n/// Facturas electrónicas emitidas\nmodel Invoice {\n  id                  String        @id @default(cuid())\n  number              String        @unique // FAC-001, FAC-002...\n  date                DateTime\n  dueDate             DateTime\n  subtotal            Decimal       @db.Decimal(15, 2)\n  discountAmount      Decimal       @default(0) @db.Decimal(15, 2)\n  discountDescription String?\n  taxRate             Decimal       @default(0.19) @db.Decimal(5, 4) // 0.19 = 19% IVA\n  taxAmount           Decimal       @db.Decimal(15, 2)\n  total               Decimal       @db.Decimal(15, 2)\n  status              InvoiceStatus @default(DRAFT)\n  notes               String?\n\n  clientId String\n  client   Client @relation(fields: [clientId], references: [id], onDelete: Restrict)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relaciones\n  items InvoiceItem[]\n\n  @@index([clientId])\n  @@index([status])\n  @@index([dueDate])\n  @@index([number])\n  @@map(\"invoices\")\n}\n\n/// Ítems individuales dentro de una factura\nmodel InvoiceItem {\n  id          String  @id @default(cuid())\n  description String\n  quantity    Int     @default(1)\n  unitPrice   Decimal @db.Decimal(15, 2)\n  total       Decimal @db.Decimal(15, 2)\n\n  invoiceId String\n  invoice   Invoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n\n  @@index([invoiceId])\n  @@map(\"invoice_items\")\n}\n\n/// Recordatorios y alertas preventivas (renovaciones, seguimientos, etc.)\nmodel Reminder {\n  id          String           @id @default(cuid())\n  type        ReminderType\n  priority    ReminderPriority @default(MEDIA)\n  status      ReminderStatus   @default(PENDIENTE)\n  dueDate     DateTime\n  description String?\n\n  clientId String?\n  client   Client? @relation(fields: [clientId], references: [id], onDelete: Cascade)\n\n  prospectId String?\n  prospect   Prospect? @relation(fields: [prospectId], references: [id], onDelete: Cascade)\n\n  createdById String?\n  createdBy   User?   @relation(fields: [createdById], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([clientId])\n  @@index([prospectId])\n  @@index([status])\n  @@index([priority])\n  @@index([dueDate])\n  @@map(\"reminders\")\n}\n\n/// Metas de negocio con seguimiento de progreso\nmodel Goal {\n  id           String       @id @default(cuid())\n  name         String\n  description  String?\n  category     GoalCategory\n  period       GoalPeriod\n  currentValue Decimal      @default(0) @db.Decimal(15, 2)\n  targetValue  Decimal      @db.Decimal(15, 2)\n  unit         String // \"pólizas\", \"clientes\", \"COP\", \"%\", \"renovaciones\"\n  status       GoalStatus   @default(ON_TRACK)\n  trend        Decimal      @default(0) @db.Decimal(5, 2) // Porcentaje de tendencia\n  startDate    DateTime\n  endDate      DateTime\n  isActive     Boolean      @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relaciones\n  milestones GoalMilestone[]\n\n  @@index([category])\n  @@index([status])\n  @@index([isActive])\n  @@index([endDate])\n  @@map(\"goals\")\n}\n\n/// Hitos intermedios de una meta\nmodel GoalMilestone {\n  id      String  @id @default(cuid())\n  label   String // \"25%\", \"50%\", \"75%\", \"100%\"\n  value   Decimal @db.Decimal(15, 2)\n  reached Boolean @default(false)\n\n  goalId String\n  goal   Goal   @relation(fields: [goalId], references: [id], onDelete: Cascade)\n\n  @@index([goalId])\n  @@map(\"goal_milestones\")\n}\n\n/// Registro de actividad reciente del sistema (feed del dashboard)\nmodel ActivityLog {\n  id       String       @id @default(cuid())\n  action   String // \"Nueva póliza SOAT emitida\", \"Prospecto contactado\", etc.\n  type     ActivityType\n  metadata Json? // Datos adicionales según contexto\n\n  clientId String?\n  client   Client? @relation(fields: [clientId], references: [id], onDelete: SetNull)\n\n  prospectId String?\n  prospect   Prospect? @relation(fields: [prospectId], references: [id], onDelete: SetNull)\n\n  userId String?\n  user   User?   @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now())\n\n  @@index([type])\n  @@index([clientId])\n  @@index([prospectId])\n  @@index([userId])\n  @@index([createdAt])\n  @@map(\"activity_logs\")\n}\n"
}

